func bump(o Object) error {
	n, e := Num(o, "revision")
	if e != nil {
		return e
	}
	if n == 1<<63-1 {
		return Fail(409, "STATE_CONFLICT", "revision exhausted")
	}
	o["revision"] = n + 1
	o["updated_at"] = Now()
	return nil
}

