// Restore is a time reversal: even PREPARED effects might have been sent after
// the snapshot. Fence ALL unfinished effects, invalidate credentials, and force
// trusted runtime reconciliation before the existing W12 resume protocol.
func (s *Service) backupFence(ctx context.Context) (Object, error) {
	runs, e := backupObjects(s.DB, "SELECT body FROM domain_objects WHERE kind='Run' AND json_extract(body,'$.status') IN ('QUEUED','STARTING','RUNNING','CANCEL_REQUESTED','RECONCILING','LOST')")
	if e != nil {
		return nil, e
	}
	effects, e := backupObjects(s.DB, `SELECT body FROM resource_effects x WHERE sequence=(SELECT max(y.sequence) FROM resource_effects y WHERE y.project=x.project AND y.run=x.run AND y.effect_key=x.effect_key) AND json_extract(body,'$.state') IN ('PREPARED','STARTED','UNKNOWN')`)
	if e != nil {
		return nil, e
	}
	tx, e := s.DB.BeginTx(ctx, nil)
	if e != nil {
		return nil, e
	}
	defer tx.Rollback()
	// Restore-local guard survives restart and applies to every existing resume
	// route. A snapshot's old observation is never fresh reconciliation evidence.
	if _, e = tx.Exec(`CREATE TABLE IF NOT EXISTS backup_restore_barriers(project TEXT NOT NULL,run TEXT NOT NULL,restored_at TEXT NOT NULL,PRIMARY KEY(project,run));
CREATE TRIGGER IF NOT EXISTS backup_require_fresh_observation BEFORE UPDATE ON domain_objects
WHEN NEW.kind='Run' AND json_extract(NEW.body,'$.lease_epoch')>json_extract(OLD.body,'$.lease_epoch')
AND EXISTS(SELECT 1 FROM backup_restore_barriers b WHERE b.project=NEW.project AND b.run=NEW.id)
AND NOT EXISTS(SELECT 1 FROM runtime_observations o JOIN backup_restore_barriers b ON b.project=o.project AND b.run=o.run WHERE o.project=NEW.project AND o.run=NEW.id AND o.epoch=json_extract(OLD.body,'$.lease_epoch') AND o.observed_at>b.restored_at AND json_extract(o.body,'$.children_stopped')=1 AND json_extract(o.body,'$.queue_empty')=1)
BEGIN SELECT RAISE(ABORT,'RESTORE_FRESH_RECONCILIATION_REQUIRED'); END;`); e != nil {
		return nil, e
	}
	if e = EnsureClientSessionFence(ctx, tx); e != nil {
		return nil, e
	}
	if e = fenceRestoredClientQueues(tx); e != nil {
		return nil, e
	}
	if _, e = tx.Exec("UPDATE auth_credentials SET revoked=1"); e != nil {
		return nil, e
	}
	for _, r := range runs {
		if _, e = tx.Exec("INSERT INTO backup_restore_barriers(project,run,restored_at) VALUES(?,?,?) ON CONFLICT(project,run) DO UPDATE SET restored_at=excluded.restored_at", r["project_id"], r["id"], Now()); e != nil {
			return nil, e
		}
		status := "RECONCILING"
		if r["status"] == "CANCEL_REQUESTED" {
			status = "CANCEL_REQUESTED"
		}
		Merge(r, Object{"status": status, "lease_token_hash": Digest([]byte(ID() + ID())), "lease_expires_at": "1970-01-01T00:00:00Z"})
		if e = bump(r); e != nil {
			return nil, e
		}
		if e = s.put(tx, "Run", r); e != nil {
			return nil, e
		}
		if e = s.event(tx, Str(r, "project_id"), "Run", r, "restore-local-admin", ID(), "RUN_CHANGED"); e != nil {
			return nil, e
		}
	}
	for _, o := range effects {
		o["state"] = "UNKNOWN"
		o["restore_reason"] = "SNAPSHOT_MAY_PREDATE_EXTERNAL_DISPATCH"
		if e = effectAppend(tx, Str(o, "project_id"), Str(o, "run_id"), Str(o, "key"), o); e != nil {
			return nil, e
		}
	}
	if e = tx.Commit(); e != nil {
		return nil, e
	}
	return Object{"active_runs_fenced": len(runs), "effects_requiring_reconciliation": len(effects), "credentials": "REVOKED_REPROVISION_LOCALLY", "external_keys": "NOT_INCLUDED_RESTORE_SEPARATELY", "external_actions_dispatched": 0, "outbox_policy": "preserved; internal consumers deduplicate by event ID; external delivery requires provider reconciliation", "expected_differences": []any{"revoked session credentials", "relocated source roots", "active runs RECONCILING with expired leases and new revisions", "unfinished effects UNKNOWN", "restore audit events"}}, nil
}
// backup is a local administrative command; it starts no server or worker.
package main

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"researchos.local/research-os/internal/domain"
	hostboundary "researchos.local/research-os/internal/host"
	"researchos.local/research-os/internal/store"
	"strconv"
	"strings"
)

func main() {
	if e := run(); e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
}
func run() error {
	if len(os.Args) < 2 {
		return fmt.Errorf("usage: backup keygen|create|export|restore|upgrade-local [flags]")
	}
	command := os.Args[1]
	f := flag.NewFlagSet(command, flag.ContinueOnError)
	source := f.String("db", "", "existing source SQLite database")
	backup := f.String("backup", "", "existing encrypted backup directory")
	out := f.String("out", "", "new destination (must not exist)")
	keyfile := f.String("key-file", "", "separate recovery key file; never command-line key bytes")
	root := f.String("root", ".", "matching application repository root")
	asDataRoot := f.Bool("as-data-root", false, "restore an operational data root (researchos.sqlite plus fresh Host bindings)")
	sourceRoot := f.String("source-root", "", "upgrade: exact schema13 release root")
	sourceProgram := f.String("source-program", "", "upgrade: preserved matching old program")
	targetProgram := f.String("target-program", "", "upgrade: reviewed target program")
	plan := f.String("plan", "", "upgrade: schema13-to14-remote-access-v1 or schema13-to20-research-runtime-v1 (exact releases only)")
	if e := f.Parse(os.Args[2:]); e != nil {
		return e
	}
	if f.NArg() != 0 {
		return fmt.Errorf("unexpected positional arguments")
	}
	if *keyfile == "" {
		return fmt.Errorf("--key-file required")
	}
	if command == "keygen" {
		key := make([]byte, 32)
		if _, e := rand.Read(key); e != nil {
			return e
		}
		f, e := os.OpenFile(*keyfile, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
		if e != nil {
			return e
		}
		defer f.Close()
		if _, e = f.Write(key); e != nil {
			return e
		}
		if e = f.Sync(); e != nil {
			return e
		}
		fmt.Println(`{"status":"KEY_CREATED_SEPARATELY","key_bytes_printed":false}`)
		return nil
	}
	if command != "create" && command != "export" && command != "restore" && command != "upgrade-local" {
		return fmt.Errorf("unknown command")
	}
	if *out == "" {
		return fmt.Errorf("--out required")
	}
	if command == "upgrade-local" {
		r, e := domain.UpgradeLocal(context.Background(), domain.LocalUpgradeOptions{
			Source: *source, Snapshot: *backup, Destination: *out, KeyFile: *keyfile,
			SourceRoot: *sourceRoot, TargetRoot: *root, SourceProgram: *sourceProgram,
			TargetProgram: *targetProgram, Plan: *plan,
		})
		if e != nil {
			return e
		}
		return json.NewEncoder(os.Stdout).Encode(r)
	}
	keyPath, e := filepath.Abs(*keyfile)
	if e != nil {
		return e
	}
	for _, dir := range []string{*out, *backup} {
		if dir == "" {
			continue
		}
		abs, e := filepath.Abs(dir)
		if e != nil {
			return e
		}
		rel, e := filepath.Rel(abs, keyPath)
		if e == nil && filepath.IsLocal(rel) {
			return fmt.Errorf("KEY_MUST_BE_OUTSIDE_BACKUP_AND_RESTORE")
		}
	}
	key, e := os.ReadFile(*keyfile)
	if e != nil || len(key) != 32 {
		return fmt.Errorf("BACKUP_KEY_UNAVAILABLE")
	}
	defer clear(key)
	contracts, e := domain.LoadContracts(filepath.Join(*root, "spec/v2.0/contracts"))
	if e != nil {
		return e
	}
	ctx := context.Background()
	hostConfig := func(db *sql.DB, dataRoot string) hostboundary.Config {
		return hostboundary.Config{DB: db, Dir: filepath.Join(dataRoot, "host"),
			ContractsDir:  filepath.Join(*root, "spec", "v2.0", "contracts"),
			MigrationFile: filepath.Join(*root, "migrations", "sqlite", "0002_domain.sql"),
			SchemaDir:     filepath.Join(*root, "internal", "api", "contracts")}
	}
	if command == "restore" {
		if *backup == "" {
			return fmt.Errorf("--backup required")
		}
		files, e := filepath.Glob(filepath.Join(*root, "migrations/sqlite/[0-9][0-9][0-9][0-9]_*.sql"))
		if e != nil {
			return e
		}
		versions := []int{}
		for _, file := range files {
			v, e := strconv.Atoi(filepath.Base(file)[:4])
			if e != nil {
				return e
			}
			versions = append(versions, v)
		}
		target := func(ctx context.Context, destination string, requests []domain.WorkspaceRestoreRequest) ([]domain.WorkspaceRestorePin, error) {
			restored, err := store.Open(filepath.Join(destination, "researchos.sqlite"))
			if err != nil {
				return nil, err
			}
			defer restored.Close()
			h, err := hostboundary.New(hostConfig(restored, destination))
			if err != nil {
				return nil, err
			}
			if _, err := h.BootstrapOwner(ctx); err != nil {
				return nil, err
			}
			pins := make([]domain.WorkspaceRestorePin, 0, len(requests))
			for _, request := range requests {
				pin, err := h.PinRestoredWorkspace(ctx, request)
				if err != nil {
					return nil, err
				}
				pins = append(pins, pin)
			}
			return pins, nil
		}
		options := domain.RestoreOptions{Key: key, SupportedMigrations: versions, Contracts: contracts}
		if *asDataRoot {
			options.WorkspaceTarget = target
			options.DatabaseName = "researchos.sqlite"
		}
		r, e := domain.RestoreBackup(ctx, *backup, *out, options)
		if e != nil {
			return e
		}
		return json.NewEncoder(os.Stdout).Encode(r)
	}
	if *source == "" {
		return fmt.Errorf("--db required")
	}
	st, e := os.Stat(*source)
	if e != nil || !st.Mode().IsRegular() {
		return fmt.Errorf("existing regular source database required")
	}
	// Refuse ambiguous URI DSNs; --db is an ordinary local file path.
	if strings.Contains(*source, "?") {
		return fmt.Errorf("SQLite URI parameters prohibited")
	}
	db, e := store.Open(*source)
	if e != nil {
		return e
	}
	defer db.Close()
	s := &domain.Service{DB: db, Contracts: contracts}
	var active int
	if e := db.QueryRow(`SELECT count(*) FROM domain_objects WHERE project='' AND kind=? AND json_extract(body,'$.status')=?`,
		domain.KindWorkspaceBinding, domain.WorkspaceActive).Scan(&active); e != nil {
		return e
	}
	var m domain.BackupManifest
	if active == 0 {
		m, e = s.CreateBackup(ctx, *out, key)
	} else {
		h, hostErr := hostboundary.New(hostConfig(db, filepath.Dir(*source)))
		if hostErr != nil {
			return hostErr
		}
		m, e = s.CreateBackupWithWorkspaces(ctx, *out, key, h)
	}
	if e != nil {
		return e
	}
	return json.NewEncoder(os.Stdout).Encode(m)
}
